using System;using System.Collections.Generic;using System.IO;using System.Net;using System.Net.Sockets;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Web.Script.Serialization;
internal sealed class NetDirectoryClient {
 readonly Uri endpoint;internal NetDirectoryClient(Uri value){if(value==null||(value.Scheme!="http"&&value.Scheme!="https")||value.UserInfo.Length!=0)throw new ArgumentException("Invalid NET directory address.");endpoint=value;}
 string Request(string path,object data){var request=(HttpWebRequest)WebRequest.Create(new Uri(endpoint,path));request.Method=data==null?"GET":"POST";request.Accept="application/json";request.Timeout=6000;request.ReadWriteTimeout=6000;request.AllowAutoRedirect=false;if(data!=null){byte[] bytes=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(data));if(bytes.Length>8192)throw new InvalidDataException("Directory request too large.");request.ContentType="application/json";request.ContentLength=bytes.Length;using(var stream=request.GetRequestStream())stream.Write(bytes,0,bytes.Length);}using(var response=(HttpWebResponse)request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream(),Encoding.UTF8)){var s=new StringBuilder();char[] buf=new char[4096];int n;while((n=reader.Read(buf,0,buf.Length))>0){if(s.Length+n>262144)throw new InvalidDataException("Directory response too large.");s.Append(buf,0,n);}return s.ToString();}}
 internal void Publish(string id,string secret,string cookie,string bearer,byte[] advert){Request("/publish",new{id=id,secret=secret,cookie=cookie,bearer=bearer,advert=Convert.ToBase64String(advert)});}
 internal void Remove(string id,string secret){Request("/remove",new{id=id,secret=secret});}
 internal List<LanServer> List(){var result=new List<LanServer>();var root=new JavaScriptSerializer().DeserializeObject(Request("/rooms",null)) as IDictionary<string,object>;object value;if(root==null||!root.TryGetValue("rooms",out value))throw new InvalidDataException("Invalid server list.");var items=value as object[];if(items==null)throw new InvalidDataException("Invalid server list.");if(items.Length>256)throw new InvalidDataException("Too many servers.");foreach(object obj in items){var entry=obj as IDictionary<string,object>;object ipValue,adValue;IPAddress ip;try{if(entry==null||!entry.TryGetValue("ip",out ipValue)||!entry.TryGetValue("advert",out adValue)||!IPAddress.TryParse(Convert.ToString(ipValue),out ip)||ip.AddressFamily!=AddressFamily.InterNetwork)continue;var room=LanDiscovery.Decode(Convert.FromBase64String(Convert.ToString(adValue)),new IPEndPoint(ip,8888));if(room!=null)result.Add(room);}catch(FormatException){}}return result;}
}
internal sealed class NetRoomLease {
 readonly object sync=new object();readonly NetDirectoryClient client;readonly string cookie,bearer,id,secret;bool closed;
 internal NetRoomLease(NetDirectoryClient directory,string accountCookie,string accountBearer){client=directory;cookie=accountCookie;bearer=accountBearer;id=Guid.NewGuid().ToString("N");byte[] bytes=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(bytes);secret=BitConverter.ToString(bytes).Replace("-","").ToLowerInvariant();Array.Clear(bytes,0,bytes.Length);}
 internal bool Publish(byte[] data){lock(sync){if(closed)return false;client.Publish(id,secret,cookie,bearer,data);return true;}}
 internal void Close(){lock(sync){if(closed)return;closed=true;try{client.Remove(id,secret);}catch(Exception){}}}
}
internal sealed partial class LauncherForm {
 readonly List<LanServer> _netRooms=new List<LanServer>();readonly Dictionary<string,List<LanServer>> _netRoomsByMaster=new Dictionary<string,List<LanServer>>(StringComparer.OrdinalIgnoreCase);DateTime _nextNetPoll=DateTime.MinValue,_nextNetPublish=DateTime.MinValue,_nextNetError=DateTime.MinValue;int _netPollBusy,_netPublishBusy;NetRoomLease _netLease;private bool _dedicatedServer;
 string ActivePlayerName {get{return _netMode&&_onlineIdentity!=null?_onlineIdentity.Name:_name.Text.Trim();}}
 internal const string DefaultNetDirectory="http://217.199.220.41:18900/";
 static Uri NormalizeNetDirectory(string value){value=(value??"").Trim();if(value.Length==0)value=DefaultNetDirectory;bool scheme=value.StartsWith("http://",StringComparison.OrdinalIgnoreCase)||value.StartsWith("https://",StringComparison.OrdinalIgnoreCase);if(!scheme){string raw=value.TrimEnd('/');if(raw.IndexOf('/')>=0)throw new InvalidDataException("Master address must not contain a path.");value="http://"+raw+(raw.IndexOf(':')<0?":18900":"")+"/";}Uri uri;if(!Uri.TryCreate(value,UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https")||uri.UserInfo.Length!=0||uri.Query.Length!=0||uri.Fragment.Length!=0||uri.AbsolutePath!="/"||String.IsNullOrWhiteSpace(uri.Host))throw new InvalidDataException("Enter a valid master server address, for example 217.199.220.41:18900.");return uri;}
 static List<Uri> NormalizeNetDirectories(string value){var result=new List<Uri>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string part in (value??"").Split(new[]{'\r','\n',',',';'},StringSplitOptions.RemoveEmptyEntries)){string item=part.Trim();if(item.Length==0)continue;Uri uri=NormalizeNetDirectory(item);if(seen.Add(uri.AbsoluteUri)){if(result.Count>=8)throw new InvalidDataException("You can configure up to 8 master servers.");result.Add(uri);}}if(result.Count==0)result.Add(NormalizeNetDirectory(DefaultNetDirectory));return result;}
 List<Uri> NetDirectoryAddresses(){string path=Path.Combine(_dir,"Saved","PUBG2019Directory.txt"),value=File.Exists(path)?File.ReadAllText(path,Encoding.UTF8):DefaultNetDirectory;return NormalizeNetDirectories(value);}
 Uri NetDirectoryAddress(){return NetDirectoryAddresses()[0];}
 string NetDirectoryAddressText(){var values=new List<string>();foreach(var uri in NetDirectoryAddresses())values.Add(uri.AbsoluteUri);return String.Join(Environment.NewLine,values.ToArray());}
 void SaveNetDirectoryAddresses(List<Uri> addresses){if(addresses==null||addresses.Count==0)throw new ArgumentException("At least one master server is required.");string path=Path.Combine(_dir,"Saved","PUBG2019Directory.txt");if(addresses.Count==1&&addresses[0].AbsoluteUri==DefaultNetDirectory){if(File.Exists(path))File.Delete(path);}else{Directory.CreateDirectory(Path.GetDirectoryName(path));var values=new List<string>();foreach(var uri in addresses)values.Add(uri.AbsoluteUri);string temp=path+".new";File.WriteAllText(temp,String.Join(Environment.NewLine,values.ToArray()),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}_netGeneration++;_netRooms.Clear();_netRoomsByMaster.Clear();_nextNetPoll=DateTime.MinValue;_nextNetError=DateTime.MinValue;CloseNetLease();}
 void SaveNetDirectoryAddress(Uri uri){SaveNetDirectoryAddresses(new List<Uri>{uri});}
 void RebuildNetRooms(List<Uri> addresses){var merged=new Dictionary<string,LanServer>(StringComparer.OrdinalIgnoreCase);foreach(var address in addresses){List<LanServer> rooms;if(!_netRoomsByMaster.TryGetValue(address.AbsoluteUri,out rooms))continue;foreach(var room in rooms)if(!String.IsNullOrEmpty(room.Address)&&!merged.ContainsKey(room.Address))merged.Add(room.Address,room);}_netRooms.Clear();_netRooms.AddRange(merged.Values);}
 sealed class MasterQueryBatch {internal int Remaining;internal MasterQueryBatch(int count){Remaining=count;}}
 void NetDirectoryNotice(string text){if(DateTime.UtcNow<_nextNetError)return;_nextNetError=DateTime.UtcNow.AddSeconds(30);AppendLog("DIRECTORY: "+text);}
 void NetDirectoryTick(){if(!_netMode||_onlineIdentity==null)return;DateTime now=DateTime.UtcNow;
  if(now>=_nextNetPoll&&Interlocked.CompareExchange(ref _netPollBusy,1,0)==0){_nextNetPoll=now.AddSeconds(5);int generation=_netGeneration;List<Uri> addresses;try{addresses=NetDirectoryAddresses();}catch(Exception e){Interlocked.Exchange(ref _netPollBusy,0);NetDirectoryNotice(e.Message);return;}var batch=new MasterQueryBatch(addresses.Count);foreach(Uri address in addresses){Uri current=address;ThreadPool.QueueUserWorkItem(delegate{try{List<LanServer> rooms=null;bool failed=false;try{rooms=new NetDirectoryClient(current).List();}catch(Exception){failed=true;}LanUi(delegate{if(!_netMode||generation!=_netGeneration)return;_netRoomsByMaster[current.AbsoluteUri]=rooms??new List<LanServer>();RebuildNetRooms(addresses);NativePublish();if(failed)NetDirectoryNotice("Master unavailable: "+current.Host);});}finally{if(Interlocked.Decrement(ref batch.Remaining)==0)Interlocked.Exchange(ref _netPollBusy,0);}});}}
  if(_lobbyServer==null||!_visibleLan){if(_netLease!=null)CloseNetLease();return;}if(now<_nextNetPublish||Interlocked.CompareExchange(ref _netPublishBusy,1,0)!=0)return;_nextNetPublish=now.AddSeconds(6);try{if(String.IsNullOrEmpty(_onlineIdentity.CookieHeader)&&String.IsNullOrEmpty(_onlineIdentity.BearerToken))throw new InvalidOperationException("The account server did not provide a usable session.");if(_netLease==null)_netLease=new NetRoomLease(new NetDirectoryClient(NetDirectoryAddress()),_onlineIdentity.CookieHeader,_onlineIdentity.BearerToken);var lease=_netLease;byte[] data=LanDiscovery.Encode(HostRoomDetails(true));ThreadPool.QueueUserWorkItem(delegate{try{lease.Publish(data);}catch(Exception){LanUi(delegate{if(_netMode&&_lobbyServer!=null)NetDirectoryNotice("Could not publish the room to the NET directory.");});}finally{Interlocked.Exchange(ref _netPublishBusy,0);}});}catch(Exception e){Interlocked.Exchange(ref _netPublishBusy,0);NetDirectoryNotice(e.Message);}}
 void CloseNetLease(){var old=_netLease;_netLease=null;_nextNetPublish=DateTime.MinValue;if(old!=null)ThreadPool.QueueUserWorkItem(delegate{old.Close();});}
}
